import { useState } from 'react';
import Board from './components/Board.jsx';
import { computeWinner } from './utils/winner.js';
import './App.css';

function App() {
  const [squares, setSquares] = useState(Array(9).fill(null));
  const [xIsNext, setXIsNext] = useState(true);

  const winner = computeWinner(squares);
  const isDraw = !winner && squares.every((cell) => cell !== null);

  function handleCellClick(index) {
    if (squares[index] || winner) return;
    const nextSquares = squares.slice();
    nextSquares[index] = xIsNext ? 'X' : 'O';
    setSquares(nextSquares);
    setXIsNext(!xIsNext);
  }

  function restart() {
    setSquares(Array(9).fill(null));
    setXIsNext(true);
  }

  let status;
  if (winner) {
    status = `Winner: ${winner}`;
  } else if (isDraw) {
    status = 'Draw';
  } else {
    status = `Next player: ${xIsNext ? 'X' : 'O'}`;
  }

  return (
    <div className="app">
      <h1>Tic-Tac-Toe</h1>
      <p className="status" data-testid="status">{status}</p>
      <Board squares={squares} onCellClick={handleCellClick} />
      <button type="button" className="restart" onClick={restart}>Restart</button>
    </div>
  );
}

export default App;

