import { describe, test, expect } from 'vitest';
import { render, fireEvent } from '@testing-library/react';
import '@testing-library/jest-dom';
import React from 'react';
import App from '../src/App.jsx';

const getCells = (container) =>
  Array.from(container.querySelectorAll('.square'));

const cellAt = (container, i) =>
  container.querySelector(`[data-testid="cell-${i}"]`);

const statusOf = (container) => {
  const el = container.querySelector('[data-testid="status"]');
  return el ? el.textContent : '';
};

const play = (container, indices) =>
  indices.forEach((i) => fireEvent.click(cellAt(container, i)));

describe('Tic-Tac-Toe game', () => {
  test('renders an empty 3x3 board', () => {
    const { container } = render(<App />);
    const cells = getCells(container);
    if (cells.length !== 9) {
      throw new Error(`Expected 9 cells, got ${cells.length}`);
    }
    cells.forEach((cell, i) => {
      if (cell.textContent.trim() !== '') {
        throw new Error(`Cell ${i} should start empty`);
      }
    });
  });

  test('clicking a cell marks it with the current player', () => {
    const { container } = render(<App />);
    fireEvent.click(cellAt(container, 0));
    const cell = cellAt(container, 0);
    if (cell.textContent.trim() !== 'X') {
      throw new Error('Expected X after the first click');
    }
    if (!statusOf(container).includes('Next player: O')) {
      throw new Error('Status should read "Next player: O"');
    }
  });

  test('players alternate turns correctly', () => {
    const { container } = render(<App />);
    play(container, [0, 1]);
    if (cellAt(container, 0).textContent.trim() !== 'X') {
      throw new Error('First move should be X');
    }
    if (cellAt(container, 1).textContent.trim() !== 'O') {
      throw new Error('Second move should be O (players must alternate)');
    }
  });

  test('a filled cell cannot be overwritten', () => {
    const { container } = render(<App />);
    fireEvent.click(cellAt(container, 0));
    if (cellAt(container, 0).textContent.trim() !== 'X') {
      throw new Error('Expected X in the clicked cell');
    }
    fireEvent.click(cellAt(container, 0));
    const value = cellAt(container, 0).textContent.trim();
    if (value !== 'X') {
      throw new Error(`Filled cell must keep its mark, got "${value}"`);
    }
    if (!statusOf(container).includes('Next player: O')) {
      throw new Error('Turn should still be O after the rejected click');
    }
  });

  test('rows, columns, and diagonals all trigger a win', () => {
    let { container } = render(<App />);
    play(container, [0, 3, 1, 4, 2]);
    if (!statusOf(container).includes('Winner: X')) {
      throw new Error('Expected a row win for X');
    }

    container = render(<App />).container;
    play(container, [2, 0, 4, 5, 6]);
    if (!statusOf(container).includes('Winner: X')) {
      throw new Error('Expected a diagonal win for X (indices 2-4-6)');
    }

    container = render(<App />).container;
    play(container, [1, 0, 4, 3, 7]);
    if (!statusOf(container).includes('Winner: X')) {
      throw new Error('Expected a column win for X (indices 1-4-7)');
    }
  });

  test('a full board with no winner is declared a draw', () => {
    const { container } = render(<App />);
    play(container, [0, 1, 2, 3, 4, 6, 5, 8, 7]);
    if (!statusOf(container).includes('Draw')) {
      throw new Error(`Expected a draw, got status "${statusOf(container)}"`);
    }
  });
});
